import{_ as t,o as a,c as r,ak as i}from"./chunks/framework.B8jO0odJ.js";const m=JSON.parse('{"title":"Chainy device checks","description":"October 26 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMat","frontmatter":{"title":"Chainy device checks","description":"October 26 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMat","source":"docs/hardware-validation.md","category":"Research & evaluation","sourceUpdated":"2026-10-26T18:51:49+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/hardware-validation.md","filePath":"content/docs/hardware-validation.md"}'),n={name:"content/docs/hardware-validation.md"};function o(s,e,d,c,l,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-device-checks">Chainy device checks<a class="header-anchor" href="#chainy-device-checks" aria-label="Link to this section">​</a></h1><p>October 26 alignment: Cryptita Plays community beta testing is November 10, 2026; pre-final is November 21. Test the adopted W01–W04 and B01–B03/demo B07 core. Wordle/BlockMatch and later teacher services are not beta acceptance blockers. Protect integration/device tests through November 6 and regression/rehearsal November 7–9.</p><p>Owners: Christian executes technical checks, Miguel checks UI, Luis checks art/import cost. Updated October 26, 2026.</p><h2 id="confirmed-minimum-reference-device">Confirmed minimum reference device<a class="header-anchor" href="#confirmed-minimum-reference-device" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Item</th><th>Confirmed minimum / interpretation</th></tr></thead><tbody><tr><td>Device label</td><td>“vivo 2019” as displayed by the supplied phone; exact retail model and chipset are not inferred</td></tr><tr><td>Android</td><td>Android 10 (API level 29) minimum; Funtouch OS 10 is the displayed vendor software layer</td></tr><tr><td>RAM</td><td>4 GB physical RAM</td></tr><tr><td>Storage</td><td>128 GB total device capacity; this is not required free space or the game&#39;s install-size allowance</td></tr><tr><td>CPU</td><td>Reported 2.3 GHz octa-core processor</td></tr><tr><td>ABI / packaging</td><td>ARM64 remains a provisional build target; confirm it from the installed build/device rather than the screenshots</td></tr><tr><td>Graphics</td><td>OpenGL ES 3.2 or Vulkan 1.1 remains provisional; the supplied screenshots do not establish graphics API or GPU support</td></tr><tr><td>Display</td><td>Resolution, aspect ratio, density and smallest supported viewport remain to be measured</td></tr></tbody></table><p>The owner-supplied screenshots confirm the displayed Android, memory, storage and processor summary above. They also show eight cores at momentary 0.4/0.9 GHz frequencies; those readings reflect dynamic operation and do not replace the reported 2.3 GHz CPU-class requirement. Clock speed and core count alone do not predict game performance, so the installed-build result governs acceptance. The screenshots include device identifiers, so they must not be copied into the repository, issues, test records or publications.</p><p>The supplied design uses Unity, but the exact render pipeline, SQLite binding, device ABI, graphics API and tested APK are not established by these screenshots. Christian records these on CH-03/04. Engine/editor success and a settings screenshot are not evidence that Chainy runs on Android.</p><h2 id="test-the-actual-game">Test the actual game<a class="header-anchor" href="#test-the-actual-game" aria-label="Link to this section">​</a></h2><p>Install the build on the confirmed minimum reference phone. Test movement/collision, dialogue, scene switching, W01–W04, B01–B03/demo B07, contextual Quiz and local profile/save/reload in airplane mode. A higher-spec phone does not replace this minimum-device pass. If the reference phone is unavailable, record the substitute&#39;s specifications and treat the minimum-device claim as still open. Teacher services and standalone modes are later checks, not beta prerequisites.</p><p>Record the non-sensitive device label, Android version, build/revision, free space, resolution, graphics path, visible stalls, memory/performance readings where available, load/save times and any overheating or crash. Never record IMEI, MAC address, serial number, phone number or account identifiers. Test a complete expected beta session, not only an empty scene.</p><p>Recommendation: aim for steady 30 FPS initially and review readable controls on the smallest target display. This is a proposed target, not measured performance. Set additional budgets only when the representative level provides useful measurements.</p><p>If performance fails, reduce unnecessary scenery, expensive effects and texture size before changing the learning rules. Test the existing player controller&#39;s speed, rotation and collision on the phone even though it is reported completed.</p><h2 id="required-handoff">Required handoff<a class="header-anchor" href="#required-handoff" aria-label="Link to this section">​</a></h2><p>CH-03: reproducible installed APK and source/build instructions, including minimum-device installation and launch evidence. CH-04: two local profiles, saved result reload and failure recovery. CH-14: W01–W04 and B01–B03/demo B07, atomic economy/quest saving, interrupted play and signed update on the minimum reference phone and any additional beta devices. Verify any approved minimal collection path separately; standalone modes and the broad teacher platform are later scope.</p><p><strong>Cryptita Plays community beta November 10; pre-final November 21, 2026.</strong> Integration/device readiness checks are planned for October 31–November 6, followed by regression/rehearsal November 7–9. No supported-device claim is made until these checks pass.</p></div>',1)])])}const u=t(n,[["render",o]]);export{m as __pageData,u as default};
